const body = $json?.body && typeof $json.body === 'object' && !Array.isArray($json.body) ? $json.body : null;
if (!body) throw new Error('request body must be a JSON object');
const allowedTopLevel = ['input','max_output_tokens','model','service_tier','store','text'];
const actualTopLevel = Object.keys(body).sort();
if (actualTopLevel.length !== allowedTopLevel.length || actualTopLevel.some((key, index) => key !== allowedTopLevel[index])) throw new Error('request fields do not match the extraction gateway contract');
if (body.model !== 'claude-sonnet-5') throw new Error('model must be claude-sonnet-5');
if (body.service_tier !== 'default' || body.store !== false) throw new Error('service_tier/store contract is invalid');
if (!Number.isSafeInteger(body.max_output_tokens) || body.max_output_tokens < 256 || body.max_output_tokens > 20000) throw new Error('max_output_tokens is outside the bounded contract');
if (!Array.isArray(body.input) || body.input.length !== 2) throw new Error('input must contain exactly system and user messages');
const readMessage = (item, role, maximum) => {
  if (!item || item.role !== role || !Array.isArray(item.content) || item.content.length !== 1) throw new Error(`${role} message contract is invalid`);
  const part = item.content[0];
  if (!part || part.type !== 'input_text' || typeof part.text !== 'string') throw new Error(`${role} content must be one input_text part`);
  const value = part.text;
  if (!value.trim() || value.length > maximum || /[\u0000]/.test(value)) throw new Error(`${role} content is empty, oversized, or unsafe`);
  return value;
};
const systemPrompt = readMessage(body.input[0], 'system', 12000);
const userPrompt = readMessage(body.input[1], 'user', 140000);
if (!systemPrompt.startsWith('You extract procurement requirements as evidence only.')) throw new Error('system prompt identity is invalid');
const initialPrompt = userPrompt.startsWith('Allowed attachment IDs:');
const correctivePrompt = userPrompt.startsWith('FINAL CORRECTIVE RETRY.') && userPrompt.includes('Allowed attachment IDs:');
if ((!initialPrompt && !correctivePrompt) || !userPrompt.includes('\n\nSOURCE:\n')) throw new Error('user prompt identity is invalid');
const format = body.text?.format;
if (!format || format.type !== 'json_schema' || format.name !== 'pai_loop_requirements' || format.strict !== true) throw new Error('strict response format is invalid');
const schema = format.schema;
if (!schema || typeof schema !== 'object' || Array.isArray(schema) || schema.type !== 'object' || schema.additionalProperties !== false || !schema.properties || typeof schema.properties !== 'object' || !Array.isArray(schema.required)) throw new Error('response JSON schema boundary is invalid');
const schemaJson = JSON.stringify(schema);
if (!schemaJson || schemaJson.length > 64000) throw new Error('response JSON schema is oversized');
const combinedCharacters = systemPrompt.length + userPrompt.length + schemaJson.length;
if (combinedCharacters > 210000) throw new Error('combined Claude request is oversized');
const schemaInstruction = `\n\nReturn only one JSON object matching this schema exactly. Do not wrap it in Markdown. RESPONSE JSON SCHEMA:\n${schemaJson}`;
return [{ json: { system_prompt: systemPrompt, user_prompt: userPrompt + schemaInstruction, max_output_tokens: body.max_output_tokens } }];

const rawOutput = String($json?.text ?? '');
if (!rawOutput.trim() || rawOutput.length > 500000) throw new Error('Claude output is empty or oversized');
let outputText = rawOutput.trim();
if (outputText.includes('```')) {
  const fenceMarkers = outputText.match(/```/g) ?? [];
  if (fenceMarkers.length !== 2) throw new Error('Claude output contains multiple Markdown fences');
  const fenced = /^```(?:json)?\r?\n([\s\S]*?)\r?\n```$/.exec(outputText);
  if (!fenced) throw new Error('Claude output fence must contain only one JSON block without prose');
  outputText = fenced[1].trim();
}
let parsed;
try { parsed = JSON.parse(outputText); } catch { throw new Error('Claude output is not valid JSON'); }
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('Claude output must be one plain JSON object');
outputText = JSON.stringify(parsed);
let tokenUsage = null;
try {
  const rows = $('Claude Sonnet 5').all();
  const candidate = rows.length ? rows[rows.length - 1]?.json?.tokenUsage : null;
  if (candidate && typeof candidate === 'object') tokenUsage = candidate;
} catch {}
const counter = (value) => Number.isSafeInteger(value) && value >= 0 && value <= 10000000 ? value : null;
const inputTokens = counter(tokenUsage?.promptTokens);
const outputTokens = counter(tokenUsage?.completionTokens);
const totalTokens = counter(tokenUsage?.totalTokens);
const executionId = String($execution.id ?? '').replace(/[^A-Za-z0-9_-]/g, '').slice(0, 80);
if (!executionId) throw new Error('n8n execution id is unavailable');
return [{ json: { id: `pai_claude_${executionId}`, status: 'completed', model: 'claude-sonnet-5', output_text: outputText, usage: { input_tokens: inputTokens, output_tokens: outputTokens, total_tokens: totalTokens } } }];
